import { test, expect } from '@playwright/test';

test.describe('Inline Table Row Editing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should allow inline editing of a table row without opening a modal', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table rows are visible
    const rows = page.getByRole('row');
    await expect(rows).toHaveCount(3);

    // Get the first editable cell using getByRole('cell')
    const firstCell = page.getByRole('cell', { name: /John Doe/i });
    await expect(firstCell).toBeVisible();

    // Click the cell to enter edit mode
    await firstCell.click();

    // Verify input field appears
    const inputField = page.getByRole('textbox');
    await expect(inputField).toBeVisible();

    // Type new value
    await inputField.fill('Jane Doe');

    // Verify input field has new value
    await expect(inputField).toHaveValue('Jane Doe');

    // Press Enter to save
    await inputField.press('Enter');

    // Verify input field disappears and cell content is updated
    await expect(inputField).not.toBeVisible();
    await expect(firstCell).toContainText('Jane Doe');

    // Verify save confirmation message appears
    const successMessage = page.getByText('Updated successfully');
    await expect(successMessage).toBeVisible();

    // Verify table row is still visible
    await expect(rows).toHaveCount(3);
  });

  test('should handle cancellation of inline edit and revert to original value', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get the second editable cell using getByRole('cell')
    const secondCell = page.getByRole('cell', { name: /Jane Smith/i });
    await expect(secondCell).toBeVisible();

    // Click the cell to enter edit mode
    await secondCell.click();

    // Verify input field appears
    const inputField = page.getByRole('textbox');
    await expect(inputField).toBeVisible();

    // Type new value
    await inputField.fill('Jane Smith Jr');

    // Verify input field has new value
    await expect(inputField).toHaveValue('Jane Smith Jr');

    // Press Escape to cancel
    await inputField.press('Escape');

    // Verify input field disappears
    await expect(inputField).not.toBeVisible();

    // Verify cell content reverts to original value
    await expect(secondCell).toContainText('Jane Smith');

    // Verify no success message appears
    const successMessage = page.getByText('Updated successfully');
    await expect(successMessage).not.toBeVisible();

    // Verify table row is still visible
    await expect(rows).toHaveCount(3);
  });
});
